<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}
final class Allocations {
 static function singleWithReturn(\PDO $db,array $actor,string $external,string $invoice,int $expectedPaid,int $expectedInvoice,string $name):array{permit($actor,'operate');return transaction($db,function()use($db,$actor,$external,$invoice,$expectedPaid,$expectedInvoice,$name){$p=one($db,'SELECT * FROM netopia_payments WHERE canonical_external_id=? FOR UPDATE',[$external]);$i=one($db,'SELECT * FROM invoices WHERE invoice_number=? FOR UPDATE',[$invoice]);if(!$p||!$i||(int)$p['gross_amount_cents']!==$expectedPaid||(int)$i['amount_cents']!==$expectedInvoice||$i['scope']==='internal'||$expectedInvoice<=0||$expectedPaid<=$expectedInvoice)throw new Problem('Documentele nu mai corespund confirmării.');$old=one($db,"SELECT id FROM decisions WHERE payment_id=? AND action='netopia_allocated' AND active=1",[$p['id']]);if($old){$rows=self::rows($db,(int)$i['id']);if(count($rows)===1&&(int)$rows[0]['id']===(int)$p['id']&&(int)$rows[0]['allocation']['amount_cents']===$expectedInvoice)return ['saved'=>true,'repeated'=>true];throw new Problem('Plata are deja altă repartizare.');}if(one($db,'SELECT payment_id FROM '.Topups::links().' l WHERE payment_id=? OR invoice_id=?',[$p['id'],$i['id']])||self::rows($db,(int)$i['id']))throw new Problem('Plata sau factura este deja atribuită.');$held=$expectedPaid-$expectedInvoice;ReturnReview::partial($db,$actor,$external,$held,$name);$proof=['invoice_hash'=>$i['source_hash'],'payment_hash'=>$p['source_hash'],'amount_cents'=>$expectedInvoice,'invoice_amount_cents'=>$expectedInvoice,'discount_cents'=>0,'discount_invoice'=>null];decision($db,'netopia_allocation',['invoice'=>$i['id'],'payment'=>$p['id']],$proof,'Repartizare explicit confirmată de utilizator. Diferența plății rămâne la retur parțial, restituire de verificat.',$actor,'allocation:'.bin2hex(random_bytes(16)),0);decision($db,'netopia_allocated',['payment'=>$p['id']],['allocated_cents'=>$expectedInvoice,'return_review_cents'=>$held,'invoices'=>[$invoice=>$expectedInvoice]],'Factură acoperită integral; diferența nu este declarată restituită, ci păstrată pentru verificare.',$actor,'allocation-group:'.bin2hex(random_bytes(16)));audit($db,'netopia_allocated',['payment'=>$external,'invoice'=>$invoice,'allocated_cents'=>$expectedInvoice,'return_review_cents'=>$held],$actor);return ['saved'=>true,'allocated_cents'=>$expectedInvoice,'return_review_cents'=>$held];});}
 static function paymentRows(\PDO $db,int $payment):array{$rows=query($db,"SELECT i.invoice_number,d.source_hashes_json FROM decisions d JOIN invoices i ON i.id=d.invoice_id WHERE d.payment_id=? AND d.action='netopia_allocation' AND d.active=1 ORDER BY i.invoice_number",[$payment])->fetchAll();foreach($rows as &$r)$r['allocation']=json_decode($r['source_hashes_json'],true);return $rows;}
 static function amountSQL(string $id):string{return "COALESCE((SELECT SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(ad.source_hashes_json,'$.amount_cents')) AS SIGNED)) FROM decisions ad JOIN netopia_payments ap ON ap.id=ad.payment_id WHERE ad.invoice_id=$id AND ad.action='netopia_allocation' AND ad.active=1 AND ap.transfer_date IS NOT NULL),0)";}
 static function rows(\PDO $db,int $invoice):array{$rows=query($db,"SELECT p.*,d.source_hashes_json AS allocation_proof FROM decisions d JOIN netopia_payments p ON p.id=d.payment_id WHERE d.invoice_id=? AND d.action='netopia_allocation' AND d.active=1",[$invoice])->fetchAll();foreach($rows as &$r)$r['allocation']=json_decode($r['allocation_proof'],true);return $rows;}
 static function enrich(\PDO $db,array &$r):void{$rows=self::rows($db,(int)$r['id']);if(!$rows)return;$p=$rows[0];$a=$p['allocation'];$r['payment_id']=$p['id'];$r['payment_method']='NETOPIA';$r['method_declared']=false;$r['gross_amount_cents']=(int)$a['amount_cents'];$r['transfer_amount_cents']=$p['transfer_date']?(int)$a['amount_cents']:null;$r['transfer_date']=$p['transfer_date'];$r['operation_number']=$p['operation_number'];$r['commission_cents']=null;$r['source_review']=(bool)$r['pending_changes']||$a['invoice_hash']!==$r['source_hash']||$a['payment_hash']!==$p['source_hash'];$r['allocation_discount_cents']=$a['discount_cents'];}
}
